// The low-detail world map of the region step (BR-SET-06): which countries a
// region highlights, and the camera that frames them. The map data is
// generated by `bun run map:generate` (see scripts/world-map.ts).

import world from './world-map.json';

/** A rectangle on the map, in the map's units: 0–1000 across, y downwards. */
export interface Box {
  x0: number;
  y0: number;
  x1: number;
  y1: number;
}

/** A country, or a territory without a country code, as the map draws it. */
export interface MapShape {
  /** ISO 3166-1 alpha-2 code, e.g. "FR", or null for e.g. Somaliland. */
  code: string | null;
  /** SVG path data in the map's units. */
  path: string;
  /** The box around the country's mainland, as x0, y0, x1, y1. */
  focus: number[];
}

/** A disputed area a region's country is party to, as administrator or claimant. */
export interface DisputedArea {
  /** SVG path data in the map's units; `""` for an island too small to outline. */
  path: string;
  /** The box around the area, as x0, y0, x1, y1. */
  box: number[];
}

/** The map's size in its own units, every shape on it, its large lakes as one path, and its disputed areas. */
export const WORLD: {
  width: number;
  height: number;
  lakes: string;
  disputed: DisputedArea[];
  shapes: MapShape[];
} = world;

/** Areas narrower than this, in map units, get a dot so they can be seen at all. */
const DOT_BELOW = 1.5;

/** The whole map, shown for a region without countries, e.g. "Other". */
export const WORLD_BOX: Box = { x0: 0, y0: 0, x1: WORLD.width, y1: WORLD.height };

/** How much of the viewport the framed countries fill at most, so they have a margin. */
const FILL = 0.75;

/** The closest zoom, relative to the whole map, so a small country isn't blown up to a blur. */
const MAX_ZOOM = 16;

/** Where the map is looked at from: scale it, then move it by x and y, in points. */
export interface Camera {
  scale: number;
  x: number;
  y: number;
}

/**
 * Works out the part of the map a region's countries cover: the box around
 * their mainlands, so the EU is framed without French Guiana, and the US
 * without Alaska and Hawaii. Unknown codes are left out.
 * @param codes ISO 3166-1 alpha-2 codes, e.g. `["JP"]`.
 * @returns The box, or `WORLD_BOX` when none of the countries is on the map.
 */
export const regionBox = (codes: readonly string[]): Box => {
  const boxes = WORLD.shapes
    .filter((shape) => shape.code !== null && codes.includes(shape.code))
    .map(({ focus: [x0, y0, x1, y1] }) => ({ x0, y0, x1, y1 }));
  if (boxes.length === 0) {
    return WORLD_BOX;
  }
  return {
    x0: Math.min(...boxes.map((b) => b.x0)),
    y0: Math.min(...boxes.map((b) => b.y0)),
    x1: Math.max(...boxes.map((b) => b.x1)),
    y1: Math.max(...boxes.map((b) => b.y1)),
  };
};

/**
 * Works out the camera that centres `box` in a viewport and zooms in until it
 * fills most of it, but never out further than the whole map nor in further
 * than `MAX_ZOOM` times that.
 * @param viewport The map's size on screen, in points.
 * @returns The camera, e.g. `{ scale: 0.35, x: 0, y: 34.4 }` for the whole
 *   map in a 350 × 220 viewport.
 */
export const cameraFor = (box: Box, viewport: { width: number; height: number }): Camera => {
  const whole = Math.min(viewport.width / WORLD.width, viewport.height / WORLD.height);
  const fit = Math.min(
    (viewport.width * FILL) / (box.x1 - box.x0),
    (viewport.height * FILL) / (box.y1 - box.y0),
  );
  const scale = box === WORLD_BOX ? whole : Math.min(Math.max(fit, whole), whole * MAX_ZOOM);
  return {
    scale,
    x: viewport.width / 2 - ((box.x0 + box.x1) / 2) * scale,
    y: viewport.height / 2 - ((box.y0 + box.y1) / 2) * scale,
  };
};

/**
 * Joins the paths of the countries with the given codes into one, e.g. to
 * draw a region's countries in one colour.
 * @returns SVG path data, or `""` when none of the countries is on the map.
 */
export const countriesPath = (codes: readonly string[]): string =>
  WORLD.shapes
    .filter((shape) => shape.code !== null && codes.includes(shape.code))
    .map((shape) => shape.path)
    .join('');

/** Every country's path joined into one: the land, drawn without borders. */
export const landPath = (): string => WORLD.shapes.map((shape) => shape.path).join('');

/**
 * Works out the part of the map a camera shows in a viewport.
 * @returns The box seen, which may reach past the map's edges.
 */
export const visibleBox = (camera: Camera, viewport: { width: number; height: number }): Box => ({
  x0: -camera.x / camera.scale,
  y0: -camera.y / camera.scale,
  x1: (viewport.width - camera.x) / camera.scale,
  y1: (viewport.height - camera.y) / camera.scale,
});

/** Every disputed area's outline joined into one path. */
export const disputedPath = (): string => WORLD.disputed.map((area) => area.path).join('');

/**
 * Finds where to put a dot for each disputed area too small to see, e.g.
 * Takeshima, at the middle of its box.
 * @returns The dots' centres in map units.
 */
export const disputedDots = (): { x: number; y: number }[] =>
  WORLD.disputed
    .filter(({ box: [x0, y0, x1, y1] }) => Math.max(x1 - x0, y1 - y0) < DOT_BELOW)
    .map(({ box: [x0, y0, x1, y1] }) => ({ x: (x0 + x1) / 2, y: (y0 + y1) / 2 }));
